let name = function `Red -> "red" | `Green -> "green"
let more = function `Red -> "r" | `Green -> "g" | `Blue -> "b"

type basic = [ `Red | `Green ]
type extended = [ basic | `Blue ]

let describe (c : extended) =
  match c with
  | #basic as b -> "basic " ^ name b
  | `Blue -> "blue"

let () =
  print_endline (name `Red);
  print_endline (more `Blue);
  print_endline (describe `Green);
  print_endline (describe `Blue);
